<script setup>
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue';
import {RefreshCw,Search,Layers3} from 'lucide-vue-next';
import {api} from '../api.js';
import {botTime} from '../bot-state.js';
import {createEmployeeCapabilityInventory,inventorySections,inventoryLayerRows,inventoryReason,inventorySource,inventoryProfileLabel} from '../employee-capability-inventory.js';
const props=defineProps({workspace:{type:String,required:true},employee:{type:Object,required:true},revision:Number,controlEpoch:Number,active:{type:Boolean,default:false},managed:{type:Boolean,default:false}});
const emit=defineEmits(['manage']);
const ui=createEmployeeCapabilityInventory({api,wrap:reactive});const s=ui.state,query=ref('');
const subject=computed(()=>({workspace:props.workspace,employeeId:props.employee.id,ownerUserId:props.employee.owner_user_id??null,deviceId:props.employee.target_device_id??null,runtime:props.employee.runtime??null,profile:props.employee.runtime_profile??null,...(Number.isInteger(props.revision)&&props.revision>0?{revision:props.revision}:{}),...(Number.isInteger(props.controlEpoch)&&props.controlEpoch>0?{controlEpoch:props.controlEpoch}:{})}));
const sections=computed(()=>inventorySections(s.value).map(section=>({...section,visibleItems:section.items.filter(item=>`${item.name||''} ${item.description||''} ${item.packageName||''}`.toLowerCase().includes(query.value.trim().toLowerCase()))})));
const checkedAt=computed(()=>s.value?.checkedAt||s.value?.snapshot?.checkedAt);
const source=computed(()=>s.value?.source||s.value?.snapshot?.source);
const stateLabel=section=>section.historical?'上次检查记录':({ready:'已返回检查记录',partial:'部分信息待核实',unknown:'尚未核实',pending:'等待检查',offline:'电脑离线',failed:'检查未完成'}[section.state]||'尚未核实');
function ownerLabel(item){const owner=item.owner;if(!owner?.employeeId)return '当前员工检查视图；分配状态见下方';if(owner.employeeId!==props.employee.id)return '归属与当前员工不一致，需重新检查';return `当前员工${owner.profile?' · '+owner.profile:''}`;}
function manage(section){emit('manage',{section:section.key,workspace:props.workspace,employee:props.employee});}
watch(()=>[subject.value.workspace,subject.value.employeeId,subject.value.ownerUserId,subject.value.deviceId,subject.value.runtime,subject.value.profile,subject.value.revision,subject.value.controlEpoch,props.active],()=>{void ui.select(subject.value,{active:props.active});},{immediate:true});
watch(()=>[props.workspace,props.employee.id],()=>query.value='');
onBeforeUnmount(()=>ui.dispose());
</script>
<template>
  <section class="employee-capability-inventory" aria-label="当前员工能力明细" :aria-busy="s.loading||s.refreshing">
    <header class="inventory-heading"><div><p class="inventory-eyebrow"><Layers3 :size="13"/>当前员工 · {{employee.name||'数字员工'}}</p><h3>能力明细</h3><p class="inventory-intro">逐项核对技能、MCP 和业务 CLI。配置或安装完成，不代表已分配、已授权或本轮已加载。</p></div><div class="inventory-actions"><button type="button" class="bot-button" :disabled="s.loading||s.refreshing" @click="ui.load()">{{s.loading?'读取中…':'读取缓存'}}</button><button type="button" class="bot-button" :disabled="s.loading||s.refreshing||s.writeUnknown||Boolean(s.value?.pending)" @click="ui.refresh()"><RefreshCw :size="14"/>{{s.refreshing?'提交检查…':'只读刷新'}}</button></div></header>
    <div class="inventory-context"><span>{{employee.runtime||'运行时待配置'}}</span><span>{{inventoryProfileLabel(employee)}}</span><span>检查时间 · {{botTime(checkedAt)}}</span><span v-if="s.value">{{inventorySource(source)}}</span></div>
    <p v-if="s.error" class="inventory-notice inventory-error" role="alert">{{s.error}}</p><p v-if="s.notice" class="inventory-notice" role="status">{{s.notice}}</p>
    <p v-if="s.value?.pending" class="inventory-notice" role="status">等待运行电脑返回只读检查；仍保留上次记录。稍后点击“读取缓存”查看结果。</p>
    <p v-if="s.value?.stale" class="inventory-notice">这些是上次检查记录，当前配置或电脑状态已有变化。下方历史状态不代表本轮已授权或已加载，请刷新后核对。</p><p v-if="s.value?.reasonCode" class="inventory-notice">{{inventoryReason(s.value.reasonCode)}}</p><p v-if="['failed','expired'].includes(s.value?.lastAttempt?.status)" class="inventory-notice">最近刷新未完成：{{inventoryReason(s.value.lastAttempt.reasonCode||'INSPECTION_FAILED')}}</p>
    <p v-if="s.loading&&!s.value" class="inventory-empty" role="status">正在读取这位员工已有的检查记录…</p>
    <template v-else-if="s.value">
      <label class="inventory-search"><Search :size="15"/><input v-model="query" aria-label="搜索员工能力明细" placeholder="搜索技能、连接或 CLI 名称"/></label>
      <details v-for="section in sections" :key="section.key" class="inventory-section" open>
        <summary><span class="inventory-section-name">{{section.label}}<small>{{section.title}}</small></span><span class="inventory-section-state">{{stateLabel(section)}} · {{section.count===null?'数量待核实':section.count+' 项记录'}}</span></summary>
        <p v-if="section.reason" class="inventory-section-reason">{{section.reason}}</p>
        <div v-if="section.visibleItems.length" class="inventory-items"><article v-for="(item,index) in section.visibleItems" :key="item.id||item.name||index" class="inventory-item">
          <div class="inventory-item-heading"><strong>{{item.name||'名称待核实'}}</strong><span>{{item.version?'版本 '+item.version:'版本尚未返回'}}</span></div>
          <p v-if="item.description" class="inventory-description">{{item.description}}</p><p v-if="item.packageName" class="inventory-package">包名 · {{item.packageName}}</p>
          <dl class="inventory-provenance"><div><dt>来源</dt><dd>{{inventorySource(item.source)}}</dd></div><div><dt>清单归属</dt><dd>{{ownerLabel(item)}}</dd></div><div><dt>检查时间</dt><dd>{{botTime(item.checkedAt||checkedAt)}}</dd></div></dl>
          <ul class="inventory-layers" aria-label="能力各层状态"><li v-for="layer in inventoryLayerRows(item,{historical:section.historical})" :key="layer.key" :data-layer="layer.key" :data-state="layer.state" :title="layer.reason"><span>{{layer.label}}</span><strong :data-tone="layer.tone">{{layer.text}}</strong></li></ul>
          <p v-if="item.reason" class="inventory-item-reason"><span>说明 / 未完成原因</span>{{inventoryReason(item.reason)}}</p>
        </article></div>
        <p v-else class="inventory-empty">{{query && section.items.length?'没有匹配的明细。':section.empty}}</p>
        <footer v-if="managed" class="inventory-section-footer"><button type="button" class="bot-link" @click="manage(section)">{{section.key==='skills'?'前往原技能入口':section.key==='mcp'?'前往原 MCP 入口':'查看员工配置'}}</button><span>清单只读；实际调整仍由原入口完成。</span></footer>
      </details>
    </template>
    <p v-else-if="!s.error" class="inventory-empty">尚未取得这位员工的能力明细。只读刷新会请求目标电脑检查，不调用模型或执行业务任务。</p>
  </section>
</template>
<style scoped>
.employee-capability-inventory{margin:0 0 22px;padding:22px;border:1px solid var(--bot-line,#e4deeb);border-radius:14px;background:#fff;min-width:0;color:var(--bot-ink,#403747)}.inventory-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:20px}.inventory-heading h3{font-size:17px;margin:5px 0 9px;font-weight:650}.inventory-eyebrow{display:flex;align-items:center;gap:6px;color:var(--bot-muted,#81738c);font-size:11px;margin:0}.inventory-intro{font-size:12px;color:var(--bot-muted,#81738c);margin:0;line-height:1.8;max-width:560px}.inventory-actions{display:flex;gap:8px;flex-shrink:0;flex-wrap:wrap}.inventory-context{display:flex;gap:8px 15px;flex-wrap:wrap;margin:18px 0;padding:11px 0;border-top:1px solid #f0ecf4;border-bottom:1px solid #f0ecf4;font-size:11px;color:var(--bot-muted,#81738c)}.inventory-notice{background:#f6f4f8;border-left:2px solid #baabbf;padding:11px 12px;font-size:12px;line-height:1.8;margin:12px 0;color:#77647e}.inventory-error{border-color:#bc7474;color:#965555;background:#fcf6f5}.inventory-search{display:flex;align-items:center;gap:9px;padding:9px 12px;margin-bottom:14px;border:1px solid var(--bot-line,#e4deeb);border-radius:8px;color:#8d8196}.inventory-search input{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:12px}.inventory-section{border-top:1px solid #eee9f2;padding:14px 0 4px}.inventory-section summary{display:flex;align-items:center;justify-content:space-between;gap:12px;cursor:pointer;list-style:none}.inventory-section summary::after{content:'+';font-size:17px;color:#978b9f}.inventory-section[open] summary::after{content:'−'}.inventory-section-name{display:flex;align-items:baseline;gap:9px;font-size:13px;font-weight:650;flex:1}.inventory-section-name small{font-size:11px;font-weight:400;color:#8a7d94}.inventory-section-state{font-size:11px;color:#8a7d94}.inventory-section-reason{font-size:12px;color:#8a7155;line-height:1.8}.inventory-items{display:grid;gap:10px;margin:15px 0}.inventory-item{border:1px solid #ebe5ef;border-radius:10px;padding:15px;min-width:0;background:#fdfcfe}.inventory-item-heading{display:flex;justify-content:space-between;gap:12px;align-items:baseline}.inventory-item-heading strong{font-size:13px;overflow-wrap:anywhere}.inventory-item-heading>span{font-size:10px;flex-shrink:0;color:#8a7d94}.inventory-description{font-size:12px;color:#73667e;line-height:1.75;margin:7px 0}.inventory-package{font-size:10px;color:#8a7d94;overflow-wrap:anywhere}.inventory-provenance{display:flex;gap:6px 18px;flex-wrap:wrap;margin:10px 0 13px;font-size:10px;color:#8a7d94}.inventory-provenance>div{display:flex;gap:5px}.inventory-provenance dt{color:#a297aa}.inventory-provenance dd{margin:0;overflow-wrap:anywhere}.inventory-layers{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;padding:0;margin:0;list-style:none}.inventory-layers li{background:#f2eff5;border-radius:6px;padding:7px 9px;display:grid;gap:4px;min-width:0}.inventory-layers li>span{font-size:10px;color:#8a7d94}.inventory-layers strong{font-size:11px;font-weight:500;color:#8a7d94;overflow-wrap:anywhere}.inventory-layers strong[data-tone=positive]{color:#4a7a65}.inventory-layers strong[data-tone=attention]{color:#9a7845}.inventory-item-reason{font-size:11px;line-height:1.7;color:#8d7356;margin:11px 0 0}.inventory-item-reason>span{display:block;font-size:10px;color:#a39482}.inventory-empty{font-size:12px;line-height:1.9;color:#8d8196;padding:13px 0;margin:0}.inventory-section-footer{display:flex;align-items:center;gap:12px;justify-content:space-between;margin:11px 0;font-size:10px;color:#a297aa}@media(max-width:760px){.employee-capability-inventory{padding:16px}.inventory-heading{display:block}.inventory-actions{margin-top:13px}.inventory-layers{grid-template-columns:repeat(2,minmax(0,1fr))}.inventory-section-state{font-size:10px}.inventory-section-footer{align-items:flex-start;flex-direction:column;gap:5px}.inventory-item-heading{align-items:flex-start}.inventory-item-heading>span{flex-shrink:1;text-align:right}}
</style>
